import Foundation
import XCTest
@testable import ColorComposerCore

/// Solver parity against the golden-vector corpus generated by the Elixir
/// `color_matching` service (viamin/color_matching#111, corpus v1).
///
/// The corpus is committed byte-identical to upstream
/// `priv/parity/v1/corpus.json` at `Fixtures/ParityCorpus/v1/corpus.json`
/// (next to this file). See `docs/solver-parity-corpus.md` for how to refresh
/// it. Every scenario is replayed twice:
///
/// 1. **Scorer-level** — each candidate's `WeightedSquaredErrorScorer` score
///    (or exclusion) must match the corpus exactly, and the tie set, tie-broke
///    flag, earliest-wins selection, selected hex, and winning error must all
///    agree.
/// 2. **Solver-level** — a 1×1 composition solved by `CompositionSolver` (the
///    optimized contiguous fast path used in production) must pick the same
///    palette index and error, so the inline math cannot drift from the
///    scorer the corpus certifies.
///
/// A failure here means the client and server would disagree on color
/// selection — the exact divergence this suite exists to catch (ties,
/// missing-measurement exclusion, weight handling).
final class SolverParityCorpusTests: XCTestCase {
    private static let corpusVersion = 1
    private static let scoreAccuracy = 1e-12

    // MARK: - Corpus wire model (snake_case keys decoded explicitly)

    private struct ParityCorpus: Decodable {
        let algorithmVersion: Int
        let scorer: String
        let selection: String
        let missingPolicy: String
        let lightSources: [String]
        let scenarios: [Scenario]

        enum CodingKeys: String, CodingKey {
            case algorithmVersion = "algorithm_version"
            case scorer
            case selection
            case missingPolicy = "missing_policy"
            case lightSources = "light_sources"
            case scenarios
        }
    }

    private struct Scenario: Decodable {
        let id: String
        let description: String
        let palette: [Vector]
        let target: Vector
        let weights: [String: Double]
        let expected: Expected
    }

    private struct Vector: Decodable {
        let index: Int?
        let hexColor: String?
        let channels: [String: Double]

        enum CodingKeys: String, CodingKey {
            case index
            case hexColor = "hex_color"
            case channels
        }
    }

    private struct Expected: Decodable {
        let selectedIndex: Int?
        let selectedHexColor: String?
        let error: Double?
        let scores: [ScoreEntry]
        let tieBroke: Bool?
        let tiedIndices: [Int]

        enum CodingKeys: String, CodingKey {
            case selectedIndex = "selected_index"
            case selectedHexColor = "selected_hex_color"
            case error
            case scores
            case tieBroke = "tie_broke"
            case tiedIndices = "tied_indices"
        }
    }

    private struct ScoreEntry: Decodable {
        let index: Int
        let outcome: Outcome

        enum CodingKeys: String, CodingKey {
            case index
            case outcome = "score"
        }

        enum Outcome: Decodable {
            case score(Double)
            case excluded

            init(from decoder: Decoder) throws {
                let container = try decoder.singleValueContainer()
                if let value = try? container.decode(Double.self) {
                    self = .score(value)
                } else if let label = try? container.decode(String.self), label == "excluded" {
                    self = .excluded
                } else {
                    throw DecodingError.dataCorruptedError(
                        in: container,
                        debugDescription: "Expected a numeric score or the string \"excluded\"."
                    )
                }
            }
        }
    }

    // MARK: - Corpus loading

    private static func loadCorpus(file: StaticString = #filePath) throws -> ParityCorpus {
        let data = try corpusData(file: file)
        return try JSONDecoder().decode(ParityCorpus.self, from: data)
    }

    /// Locates the committed fixture. Prefers the checkout-relative path (the
    /// file sits next to this test); falls back to bundle resources for builds
    /// where the corpus is declared as a package resource.
    private static func corpusData(file: StaticString) throws -> Data {
        let sourceRelative = URL(fileURLWithPath: "\(file)")
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/ParityCorpus/v1/corpus.json")
        if FileManager.default.fileExists(atPath: sourceRelative.path) {
            return try Data(contentsOf: sourceRelative)
        }
        let bundle = Bundle(for: SolverParityCorpusTests.self)
        let bundled = [
            bundle.url(forResource: "corpus", withExtension: "json", subdirectory: "Fixtures/ParityCorpus/v1"),
            bundle.url(forResource: "corpus", withExtension: "json")
        ].compactMap { $0 }
        if let url = bundled.first {
            return try Data(contentsOf: url)
        }
        throw NSError(
            domain: "SolverParityCorpusTests",
            code: 1,
            userInfo: [
                NSLocalizedDescriptionKey: "Parity corpus fixture not found; expected it beside this test at Fixtures/ParityCorpus/v1/corpus.json. See docs/solver-parity-corpus.md for refresh instructions."
            ]
        )
    }

    // MARK: - Corpus → domain mapping

    private func domainPalette(from scenario: Scenario) throws -> [PaletteColor] {
        try scenario.palette.map { vector in
            let hex = try XCTUnwrap(vector.hexColor, "Corpus palette entry \(vector.index ?? -1) needs a hex_color")
            let rgb = try XCTUnwrap(RGBColor(hex: hex), "Corpus hex \(hex) must parse")
            var responses: [LightingCondition: IlluminationResponse] = [:]
            for (key, value) in vector.channels {
                guard let condition = LightingCondition(rawValue: key) else { continue }
                responses[condition] = IlluminationResponse(brightness: value)
            }
            return PaletteColor(id: vector.index ?? -1, hex: hex, rgb: rgb, responses: responses)
        }
    }

    /// Canonical light sources map onto `ChannelWeights`; unknown weight keys
    /// (the corpus's `ultraviolet` probe) must be dropped, never fatal.
    private func domainWeights(from scenario: Scenario) -> ChannelWeights {
        ChannelWeights(
            white: scenario.weights["white"] ?? 0,
            red: scenario.weights["red"] ?? 0,
            green: scenario.weights["green"] ?? 0,
            blue: scenario.weights["blue"] ?? 0,
            lps: scenario.weights["lps"] ?? 0
        )
    }

    private func domainTarget(from scenario: Scenario) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in scenario.target.channels {
            if let condition = LightingCondition(rawValue: key) {
                brightness[condition] = value
            }
        }
        return TargetResponseVector(brightness)
    }

    // MARK: - Corpus stamp checks

    /// The corpus carries compatibility stamps; when upstream bumps
    /// `algorithm_version` or changes the certified policy, this fails loudly
    /// so the fixture and expectations are refreshed consciously.
    func testCorpusStampsMatchWhatThisSuiteCertifies() throws {
        let corpus = try Self.loadCorpus()
        XCTAssertEqual(corpus.algorithmVersion, Self.corpusVersion, "A new corpus algorithm_version landed; refresh the fixture and this check together")
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, ["white", "red", "green", "blue", "lps"])

        let ids = Set(corpus.scenarios.map(\.id))
        XCTAssertGreaterThanOrEqual(corpus.scenarios.count, 12)
        for required in [
            "distinct-errors",
            "tie-symmetric-around-target",
            "tie-duplicate-vectors",
            "tie-three-way-on-lps",
            "missing-candidate-excluded",
            "missing-target-excluded",
            "zero-weight-channel-missing",
            "all-excluded",
            "unknown-weight-ignored",
            "exact-match-zero-error"
        ] {
            XCTAssertTrue(ids.contains(required), "Corpus is missing scenario \(required)")
        }
    }

    // MARK: - Scorer-level parity

    /// Every candidate score (or exclusion), the tie set, the tie-broke flag,
    /// the earliest-wins winner, its hex, and its error must match the corpus
    /// exactly — including the deliberate tie scenarios.
    func testScorerMatchesCorpusScoresSelectionsAndTies() throws {
        let corpus = try Self.loadCorpus()
        let scorer = WeightedSquaredErrorScorer()

        for scenario in corpus.scenarios {
            let palette = try domainPalette(from: scenario)
            let target = domainTarget(from: scenario)
            let weights = domainWeights(from: scenario)

            let actual = palette.map {
                scorer.score(candidate: $0, target: target, weights: weights)
            }
            let expectedScores = scenario.expected.scores.sorted { $0.index < $1.index }

            XCTAssertEqual(
                actual.count, expectedScores.count,
                "Scenario \(scenario.id): corpus must score every palette entry"
            )
            for (index, pair) in zip(actual, expectedScores).enumerated() {
                let (outcome, expected) = pair
                switch (outcome, expected.outcome) {
                case (.excluded, .excluded):
                    continue
                case let (.score(value), .score(expectedValue)):
                    XCTAssertEqual(
                        value, expectedValue, accuracy: Self.scoreAccuracy,
                        "Scenario \(scenario.id), palette index \(index): weighted squared error diverged from the Elixir solver"
                    )
                case (.score, .excluded):
                    XCTFail("Scenario \(scenario.id), palette index \(index): client scored a candidate the server excludes")
                case (.excluded, .score(let expectedValue)):
                    XCTFail("Scenario \(scenario.id), palette index \(index): client excluded a candidate the server scores \(expectedValue)")
                }
            }

            try assertSelection(scenario: scenario, scores: actual)
        }
    }

    /// Derives selection from the scorer's actual outputs and checks it against
    /// the corpus: minimum score, earliest index on ties, tie membership, and
    /// tie-broke evidence.
    private func assertSelection(scenario: Scenario, scores: [ScorerResult]) throws {
        let expected = scenario.expected

        var bestIndex: Int?
        var bestScore = Double.infinity
        for (index, result) in scores.enumerated() {
            guard case .score(let value) = result else { continue }
            if value < bestScore {
                bestScore = value
                bestIndex = index
            }
        }

        let tied = scores.enumerated().compactMap { (index, result) -> Int? in
            guard case .score(let value) = result, abs(value - bestScore) <= Self.scoreAccuracy else { return nil }
            return index
        }

        guard let expectedSelected = expected.selectedIndex else {
            XCTAssertNil(bestIndex, "Scenario \(scenario.id): expected no selection, client selected \(bestIndex.map(String.init) ?? "nil")")
            XCTAssertTrue(tied.isEmpty, "Scenario \(scenario.id): nothing may tie when everything is excluded")
            return
        }

        let selected = try XCTUnwrap(bestIndex, "Scenario \(scenario.id): corpus expects selection \(expectedSelected), client selected none")
        XCTAssertEqual(selected, expectedSelected, "Scenario \(scenario.id): selection diverged (earliest-wins tie policy)")
        XCTAssertEqual(paletteHex(scenario, selected), expected.selectedHexColor, "Scenario \(scenario.id): selected hex mismatch")
        if let expectedError = expected.error {
            XCTAssertEqual(bestScore, expectedError, accuracy: Self.scoreAccuracy, "Scenario \(scenario.id): winning error diverged")
        }
        XCTAssertEqual(tied, expected.tiedIndices, "Scenario \(scenario.id): tie set diverged")
        if let tieBroke = expected.tieBroke {
            XCTAssertEqual(tied.count > 1, tieBroke, "Scenario \(scenario.id): tie_broke evidence diverged")
        }
    }

    // MARK: - Solver-level parity (production fast path)

    /// Replays every solvable scenario through `CompositionSolver` — the same
    /// contiguous fast path the app uses — on a 1×1 grid built from the
    /// scenario target. The inline selection math must agree with the corpus,
    /// including ties, exclusions, and per-candidate exclusion counts.
    func testSolverFastPathMatchesCorpusSelections() throws {
        let corpus = try Self.loadCorpus()
        let solver = CompositionSolver()

        for scenario in corpus.scenarios {
            let weights = domainWeights(from: scenario)
            let active = weights.activeConditions

            // Scenarios whose target itself lacks an active channel cannot be
            // expressed as source grids (the solver always supplies target
            // values); their all-excluded outcome is covered scorer-level.
            guard active.allSatisfy({ scenario.target.channels[$0.rawValue] != nil }) else { continue }

            let palette = try domainPalette(from: scenario)
            let grids = Dictionary(
                uniqueKeysWithValues: active.compactMap { condition -> (LightingCondition, BrightnessGrid)? in
                    guard let fill = scenario.target.channels[condition.rawValue] else { return nil }
                    return (condition, BrightnessGrid(width: 1, height: 1, fill: fill))
                }
            )
            let result = try solver.solve(palette: palette, sourceGrids: grids, weights: weights)

            let expected = scenario.expected
            if let expectedIndex = expected.selectedIndex {
                let selectedIndex = try XCTUnwrap(result.colorIndex(x: 0, y: 0), "Scenario \(scenario.id): solver left the cell unmatched")
                XCTAssertEqual(selectedIndex, expectedIndex, "Scenario \(scenario.id): solver fast-path selection diverged")
                XCTAssertEqual(palette[selectedIndex].hex, expected.selectedHexColor, "Scenario \(scenario.id): solver selected the wrong hex")
                if let expectedError = expected.error {
                    XCTAssertEqual(result.error(x: 0, y: 0), expectedError, accuracy: Self.scoreAccuracy, "Scenario \(scenario.id): solver fast-path error diverged")
                }
            } else {
                XCTAssertNil(result.colorIndex(x: 0, y: 0), "Scenario \(scenario.id): expected every candidate excluded and no selection")
                XCTAssertEqual(result.error(x: 0, y: 0), .infinity, "Scenario \(scenario.id): an unmatched cell must record infinite error")
            }

            let excludedExpected = expected.scores.filter {
                if case .excluded = $0.outcome { return true }
                return false
            }.count
            XCTAssertEqual(
                result.excludedCandidateCount, excludedExpected,
                "Scenario \(scenario.id): excluded-candidate count diverged"
            )
        }
    }

    // MARK: - Helpers

    private func paletteHex(_ scenario: Scenario, _ index: Int) -> String? {
        scenario.palette.first { $0.index == index }?.hexColor
    }
}
